typedef int (*Operation)(int, int);
int add(int a, int b) { return a + b; }
int subtract(int a, int b) { return a - b; }
Operation ops[] = { add, subtract };
int perform_operation(Operation op, int x, int y) {
    return op(x, y);
}
int main() {
    int result1 = perform_operation(ops[0], 10, 5); // Calls add
    int result2 = perform_operation(ops[1], 10, 5); // Calls subtract
    return 0;
}
